    const course=courses[4];let hit=0,miss=[];
    for(const row of rows){
      const [en,zh,ph,sent,zhs,note]=row;
      const word=course.words.find(w=>w.en===en);
      const flat=t=>String(t||'').replace(/（[^）]*）|\([^)]*\)/g,'').trim();
      const use=word&&word.uses.find(u=>u.part==='n'&&(u.zh===zh||flat(u.zh)===flat(zh)));
      if(!use){miss.push(en+'|'+zh);continue;}
      use.phrase=ph;use.sentence=sent;use.sentenceZh=zhs;use.note=note;hit++;
    }
    // 两张跨词条补写：同一拼写的铅、同伴
    for(const [en,zh,sent,zhs,note] of [["lead","铅","Lead is soft and gray.","铅又软又是灰的。","lead 指那种软而重的灰金属。这句说的是它的样子，lead 是名词。"],["mate","同伴","He is my old mate.","他是我多年的老伙计。","mate 指常在一起的那个人。句中说的是那一位，mate 是名词。"]]){
      const w=course.words.find(x=>x.en===en);const u=w&&w.uses.find(x=>x.part==='n'&&x.zh===zh);
      if(u){u.phrase='';u.sentence=sent;u.sentenceZh=zhs;u.note=note;hit++;}
    }
    for(const [en,zh,sent,zhs,note] of [["adjective","形容词","Cold is an adjective.","cold 这个词是形容词。","adjective 就是「形容词」。句中说 cold 这个词是形容词，adjective 是名词。"],["adverb","副词","Soon is an adverb.","soon 这个词是副词。","adverb 就是「副词」。句中说 soon 这个词是副词，adverb 是名词。"],["pronoun","代词","It is a pronoun.","it 这个词是代词。","pronoun 就是「代词」。句中说 it 这个词是代词，pronoun 是名词。"],["determiner","限定词","This is a determiner.","this 这个词是限定词。","determiner 就是「限定词」。句中说 this 这个词是限定词，determiner 是名词。"],["preposition","介词","From is a preposition.","from 这个词是介词。","preposition 就是「介词」。句中说 from 这个词是介词，preposition 是名词。"],["conjunction","连词","And is a conjunction.","and 这个词是连词。","conjunction 就是「连词」。句中说 and 这个词是连词，conjunction 是名词。"],["interjection","感叹词","Yeah is an interjection.","yeah 这个词是感叹词。","interjection 就是「感叹词」。句中说 yeah 这个词是感叹词，interjection 是名词。"]]){
      const w=course.words.find(x=>x.en===en);const u=w&&w.uses.find(x=>x.part==='n');
      if(u){u.phrase=u.phrase;u.sentence=sent;u.sentenceZh=zhs;u.note=note;hit++;}
    }
    if(miss.length)console.warn('V64.102 noun rewrite missed:',miss.join(','));
    window.WMVocab4NounRewrite4={rows:hit,missed:miss};
